        try {
            runnable.run();
            throw new AssertionError("Expected " + expectedType.getName() + " but nothing was thrown");
        } catch (Throwable t) {
            if (!expectedType.isInstance(t)) {
                throw new AssertionError(
                        "Expected " + expectedType.getName() + " but got " + t.getClass().getName(), t);
            }
        }
    }

